pub struct EventStream<T: Batchable> {
    ring: Arc<Disruptor<T>>,
    wal_cursor: AtomicU64,
}

impl<T> EventStream<T> {
    #[inline(always)]
    pub fn append_batch(&self, batch: &[T]) -> Result<u64> {
        // Zero-allocation memory fence
        let seq = self.ring.claim(batch.len())?;
        self.wal_cursor.store(seq, Ordering::Release);
        Ok(seq)
    }
}
